// =====================================================================
// 5. SENTINEL-1 SAR COLLECTION
// =====================================================================
// v5.0 FIX. v4.3 differenced whatever scenes happened to cover the AOI,
// mixing ascending with descending passes and different relative orbits, so
// the VH difference was driven by viewing geometry rather than by surface
// water. Pin one track and one pass direction for both sides of every
// difference. Keta sits under a single 12-day track, so this costs no events.
//
// PINNED 2026-08 from the audit below, run against project keta-500021:
//   relative orbits over Keta : {74: 519, 168: 5, 66: 5}
//   pass directions           : {ASCENDING: 519, DESCENDING: 10}
// Keta sits under ONE ascending track, relative orbit 74. The 10 descending
// scenes are scattered across orbits 168 and 66 and cannot support a
// before/after pair for any event. Pinning to 74/ASCENDING keeps 519 of 529
// scenes while removing every cross-geometry comparison.
//
// The histograms below still print on every run. If they ever disagree with
// these constants, trust the histograms.
var S1_RELATIVE_ORBIT = 74;
var S1_PASS = "ASCENDING";

// Version fingerprint. This is the FIRST thing printed on every run, so there
// is never any doubt about which copy of the script is loaded in the editor.
print(">>> KETA PIPELINE v5.1 (GLO-30)  |  S1_PASS=" + S1_PASS +
      "  S1_RELATIVE_ORBIT=" + S1_RELATIVE_ORBIT +
      "  SAMPLES_PER_EVENT=" + SAMPLES_PER_EVENT +
      "  ENFORCE_GATES=" + ENFORCE_LABEL_GATES);
print(">>> If this line does not say ASCENDING / 74, the editor is running an" +
      " older paste. Select all (Ctrl+A) and replace, do not append.");

var s1All = ee.ImageCollection("COPERNICUS/S1_GRD")
  .filterBounds(keta)
  .filter(ee.Filter.eq("instrumentMode", "IW"))
  .filter(ee.Filter.listContains("transmitterReceiverPolarisation", "VH"));

print("S1 relative orbits over Keta:",
      s1All.aggregate_histogram("relativeOrbitNumber_start"));
print("S1 pass directions over Keta:",
      s1All.aggregate_histogram("orbitProperties_pass"));

var s1 = s1All
  .filter(ee.Filter.eq("orbitProperties_pass", S1_PASS))
  .filter(S1_RELATIVE_ORBIT === null
          ? ee.Filter.notNull(["relativeOrbitNumber_start"])
          : ee.Filter.eq("relativeOrbitNumber_start", S1_RELATIVE_ORBIT))
  .map(function(img) {
    var angle = img.select("angle");
    return img.updateMask(angle.gt(30).and(angle.lt(45))).select("VH");
  });

