// =====================================================================
// 6. FLOOD LABEL -- OTSU THRESHOLDING
// =====================================================================
function otsuThreshold(histogram) {
  var counts = ee.Array(ee.Dictionary(histogram).get('histogram'));
  var means  = ee.Array(ee.Dictionary(histogram).get('bucketMeans'));
  var size   = means.length().get([0]);
  var total  = counts.reduce(ee.Reducer.sum(), [0]).get([0]);
  var sum    = means.multiply(counts).reduce(ee.Reducer.sum(), [0]).get([0]);
  var mean   = sum.divide(total);

  var indices = ee.List.sequence(1, size);
  var bss = indices.map(function(i) {
    var aCounts = counts.slice(0, 0, i);
    var aCount  = aCounts.reduce(ee.Reducer.sum(), [0]).get([0]);
    var aMeans  = means.slice(0, 0, i);
    var aMean   = aMeans.multiply(aCounts).reduce(ee.Reducer.sum(), [0]).get([0]).divide(aCount);
    var bCount  = total.subtract(aCount);
    var safeBCount = ee.Number(ee.Algorithms.If(bCount.gt(0), bCount, 1));
    var bMean   = sum.subtract(aCount.multiply(aMean)).divide(safeBCount);
    var value   = aCount.multiply(bCount).multiply(aMean.subtract(bMean).pow(2));
    return ee.Number(ee.Algorithms.If(aCount.gt(0).and(bCount.gt(0)), value, 0));
  });

  var maxBssIdx = bss.indexOf(ee.List(bss).reduce(ee.Reducer.max()));
  return means.get([maxBssIdx]);
}

function getFloodLabel(event) {
  var t0 = ee.Date(event.get("start"));
  var t1 = ee.Date(event.get("end"));
  var bStart = ee.Date(event.get("base_start"));
  var bEnd   = ee.Date(event.get("base_end"));

  var beforeCol = s1.filterDate(bStart, bEnd);
  var duringCol = s1.filterDate(t0, t1);

  // v4.3 (A): coverage is now a first-class quantity. If EITHER side is
  // empty the event is invalid -- we must not fabricate a baseline.
  var nBefore = beforeCol.size();
  var nDuring = duringCol.size();
  var s1Ok    = nBefore.gt(0).and(nDuring.gt(0));   // ee.Number 1/0

  // The masked dummy is retained ONLY to guarantee band structure (the
  // median of a truly empty collection has zero bands, which would make
  // .rename() throw and kill the whole script rather than one event).
  // The critical change from v4.2 is that `.unmask(0)` is GONE: the dummy
  // is selfMask()ed, so it contributes nothing when real images exist,
  // and when the collection is empty the result stays MASKED instead of
  // becoming a physically impossible 0 dB. A masked baseline propagates
  // to a masked diff and a masked flood band, so the event yields no rows.
  var dummyVH   = ee.Image.constant(0).rename("VH").selfMask();
  var beforeImg = beforeCol.merge(ee.ImageCollection([dummyVH])).median().rename("VH_before");
  var duringImg = duringCol.merge(ee.ImageCollection([dummyVH])).median().rename("VH_during");

  var diff = duringImg.subtract(beforeImg).rename("VH_diff");

  // v5.0 FIX. Permanent water is EXCLUDED from the histogram unconditionally.
  // Labelling it dry made 61% of v4.3's rows negative by construction.
  var diffForHist = diff.updateMask(permWater.not());

  var hist = diffForHist.reduceRegion({
    reducer: ee.Reducer.histogram({maxBuckets: 255}),
    geometry: keta,
    scale: 30,
    maxPixels: 1e8
  }).get("VH_diff");

  // v5.0 FIX. Otsu returns a threshold for ANY histogram, including a unimodal
  // one, so an event with no flooding still had roughly half its pixels
  // labelled flooded. 13 of v4.3's 23 events landed between 0.43 and 0.52
  // labelled fraction, which is the signature of thresholding noise. Require
  // genuine bimodality, a physically plausible cut, and a plausible extent.
  var otsuThresh = ee.Number(ee.Algorithms.If(
    hist, otsuThreshold(hist), OTSU_FALLBACK_THRESH));
  var eta = ee.Number(ee.Algorithms.If(hist, otsuSeparability(hist), 0));

  // Bimodality dropped as a gate (see MIN_BIMODALITY). eta is still exported.
  var physicalOk = otsuThresh.lte(MIN_DROP_DB).and(otsuThresh.gte(MAX_DROP_DB));

  var rawFlood = diff.lt(otsuThresh).updateMask(permWater.not());
  var floodFrac = ee.Number(ee.Algorithms.If(hist, rawFlood.reduceRegion({
    reducer: ee.Reducer.mean(), geometry: keta, scale: 90, maxPixels: 1e8
  }).get("VH_diff"), 1));
  var extentOk = floodFrac.lte(MAX_FLOOD_FRAC);

  // extentOk is computed and exported but NOT gated: it agrees with the
  // threshold test (p = 0.013) and adds nothing once the threshold is applied.
  var gatesOk = physicalOk;
  var labelOk = ENFORCE_LABEL_GATES ? ee.Number(s1Ok).and(gatesOk)
                                    : ee.Number(s1Ok);

  var floodMask = rawFlood.rename("flood").toFloat()
    .updateMask(ee.Image.constant(labelOk));

  // QA travels with every row so the label can be audited downstream.
  var qa = ee.Image.constant(s1Ok).rename("qa_s1_ok")
    .addBands(ee.Image.constant(labelOk).rename("qa_label_ok"))
    .addBands(ee.Image.constant(gatesOk).rename("qa_gates_ok"))
    .addBands(ee.Image.constant(eta).rename("qa_otsu_separability"))
    .addBands(ee.Image.constant(otsuThresh).rename("qa_otsu_threshold_db"))
    .addBands(ee.Image.constant(floodFrac).rename("qa_flood_fraction"))
    .addBands(ee.Image.constant(nBefore).rename("qa_n_before"))
    .addBands(ee.Image.constant(nDuring).rename("qa_n_during"))
    .toFloat();

  return floodMask.addBands(diff).addBands(qa).set({
    "event_id": event.get("id"),
    "otsu_threshold": otsuThresh,
    "s1_baseline_n": nBefore,
    "s1_during_n": nDuring,
    "qa_s1_ok": s1Ok,
    "qa_label_ok": labelOk
  });
}

// ---------------------------------------------------------------------
// v4.3 (A): loud client-side coverage gate. Any "*** FAIL" line means
// that event contributes ZERO samples and must be fixed (widen the
// window or slide the baseline) before the export is trusted.
// ---------------------------------------------------------------------
print("=== v4.3 SENTINEL-1 COVERAGE GATE (FAIL => event exports no rows) ===");
events.forEach(function(e) {
  var nB = s1.filterDate(ee.Date(e.base_start), ee.Date(e.base_end)).size();
  var nD = s1.filterDate(ee.Date(e.start), ee.Date(e.end)).size();
  ee.Dictionary({baseline: nB, during: nD}).evaluate(function(d) {
    var ok = d.baseline > 0 && d.during > 0;
    print((ok ? "    ok  " : "*** FAIL ") + e.id +
          "  baseline=" + d.baseline + "  during=" + d.during);
  });
});

// =====================================================================
// 7. GPM IMERG V7
// =====================================================================
var imerg = ee.ImageCollection("NASA/GPM_L3/IMERG_V07").select("precipitation");

function getIMERG(t0, t1) {
  var dummy = ee.Image.constant(0).rename("precipitation").selfMask();
  var windowStart = t0.advance(-1, "day");
  var nDays = t1.difference(windowStart, "day").ceil().max(1);
  var dayOffsets = ee.List.sequence(0, nDays.subtract(1));

  var dailySums = ee.ImageCollection.fromImages(
    dayOffsets.map(function(d) {
      var dayStart = windowStart.advance(d, "day");
      var dayEnd   = dayStart.advance(1, "day");
      return imerg.filterDate(dayStart, dayEnd)
        .merge(ee.ImageCollection([dummy]))
        .sum().multiply(0.5).rename("precip_daily");
    })
  );

  var imerg24h = dailySums.max().unmask(0).rename("imerg_24h").toFloat();

  var imergCol = imerg.filterDate(windowStart, t1);
  var imergPeakIntensity = imergCol.merge(ee.ImageCollection([dummy]))
    .max().unmask(0).rename("imerg_peak_intensity").toFloat();

  var imerg3d = imergCol.merge(ee.ImageCollection([dummy]))
    .sum().multiply(0.5).unmask(0).rename("imerg_3d").toFloat();

  return ee.Image.cat([imerg24h, imergPeakIntensity, imerg3d]);
}

// =====================================================================
// 8. CHIRPS PRECIPITATION
// NOTE: CHIRPS DAILY (final) lags real time by ~1.5-2 months. For very
// recent events (e.g. jun2026_floodgates) the 7d/30d sums may be partly
// or fully dummy-zero. Cross-check availability before trusting
// chirps_* features on the newest events.
// =====================================================================
var chirps = ee.ImageCollection("UCSB-CHG/CHIRPS/DAILY");

function getRain(t) {
  var dummy = ee.Image.constant(0).rename("precipitation").selfMask();

  var rain7d = chirps.filterDate(t.advance(-7,  "day"), t).select("precipitation")
    .merge(ee.ImageCollection([dummy])).sum().unmask(0).rename("chirps_7d");
  var rain30d = chirps.filterDate(t.advance(-30, "day"), t).select("precipitation")
    .merge(ee.ImageCollection([dummy])).sum().unmask(0).rename("chirps_30d");
  return ee.Image.cat([rain7d, rain30d]);
}

// =====================================================================
// 9. ERA5 HOURLY -- PRESSURE & ONSHORE WIND (v4.2: pressure now real)
// =====================================================================
var era5 = ee.ImageCollection("ECMWF/ERA5/HOURLY");

function getERA5(t) {
  var c = era5.filterDate(t.advance(-3, "day"), t);

  var dummyU     = ee.Image.constant(0).rename("u_component_of_wind_10m").selfMask();
  var dummyV     = ee.Image.constant(0).rename("v_component_of_wind_10m").selfMask();
  var dummySolar = ee.Image.constant(0).rename("surface_net_solar_radiation").selfMask();
  var dummyP     = ee.Image.constant(PRESSURE_FALLBACK).rename("surface_pressure").selfMask();

  var u = c.select("u_component_of_wind_10m").merge(ee.ImageCollection([dummyU])).mean().unmask(0).rename("u_wind_10m");
  var v = c.select("v_component_of_wind_10m").merge(ee.ImageCollection([dummyV])).mean().unmask(0).rename("v_wind_10m");
  var solar = c.select("surface_net_solar_radiation").merge(ee.ImageCollection([dummySolar]))
    .mean().divide(3600).unmask(0).rename("solar_rad");

  // v4.2 FIX: surface_pressure (Pa) -- inverse barometer proxy. Was
  // announced in v4.1 but never actually built. Dummy fallback = 1 atm.
  var pressure = c.select("surface_pressure").merge(ee.ImageCollection([dummyP]))
    .mean().unmask(PRESSURE_FALLBACK).rename("surface_pressure");

  var windSpeed = u.pow(2).add(v.pow(2)).sqrt().rename("wind_speed");
  var windDir   = u.atan2(v).multiply(180 / Math.PI).rename("wind_dir");

  // Onshore Wind Component perpendicular to Keta coastline (135deg SE)
  var onshoreWind = u.multiply(-0.7071).add(v.multiply(0.7071)).rename("onshore_wind");

  return ee.Image.cat([solar, u, v, windSpeed, windDir, onshoreWind, pressure]);
}

// =====================================================================
// 10. SMAP SOIL MOISTURE (v4.2: migrated to SPL4SMGP/008)
// Old NASA_USDA/HSL/SMAP10KM_soil_moisture is deprecated; its data ends
// 2022-08-02, so all post-Aug-2022 events were silently getting the 0.2
// dummy. SPL4SMGP/008 is 3-hourly, 2015-03 to present; "sm_surface" is
// 0-5 cm volumetric soil moisture (fraction, 0-0.9), so the 0.2 default
// and the 0.1-0.5 normalization in compound_risk remain sensible.
// =====================================================================
var smap = ee.ImageCollection("NASA/SMAP/SPL4SMGP/008");

function getSM(t) {
  var col = smap.filterDate(t.advance(-5, "day"), t).select("sm_surface");
  // v4.3 (B): named constant, so a reader of the exported CSV can spot a
  // silent fallback (soil_moisture == SM_FALLBACK exactly) at a glance.
  var dummy = ee.Image.constant(SM_FALLBACK).rename("sm_surface").selfMask();
  return col.merge(ee.ImageCollection([dummy])).mean()
    .unmask(SM_FALLBACK).rename("soil_moisture");
}

// =====================================================================
// 11. HYDRODYNAMIC BANDS (FES2022)
// =====================================================================
function getHydroBands(eventId) {
  var fes = ee.Dictionary(ee.Dictionary(FES2022_DATA).get(eventId));
  var maxTide = ee.Number(fes.get("max"));

  var tideMax   = ee.Image.constant(maxTide).rename("tide_max_fes");
  var tideRange = ee.Image.constant(ee.Number(fes.get("range"))).rename("tide_range_fes");
  var spring    = ee.Image.constant(ee.Number(fes.get("spring"))).rename("spring_flag_fes");

  // Tide Anomaly (deviation from median baseline 0.75m)
  var tideAnomaly = ee.Image.constant(maxTide.subtract(0.75)).rename("tide_anomaly");

  return ee.Image.cat([tideMax, tideRange, spring, tideAnomaly]);
}

function getFreeboard(hydro, demImg) {
  return hydro.select("tide_max_fes").subtract(demImg).rename("freeboard_fes");
}

// =====================================================================
// 12. COMPOUND RISK BAND
// =====================================================================
function getCompoundRisk(imergBands, sm, hydro) {
  // v4.3 (B): tide-range bounds are now the frozen CONFIG constants, not
  // literals silently tied to the current catalogue's min/max. Values are
  // identical to v4.2, so compound_risk is unchanged for these 23 events.
  var span = COMPOUND_TIDE_RANGE_MAX - COMPOUND_TIDE_RANGE_MIN;
  var normRain = imergBands.select("imerg_24h").divide(50).clamp(0, 1);
  var normSM   = sm.subtract(0.1).divide(0.4).clamp(0, 1);
  var normTide = hydro.select("tide_range_fes")
    .subtract(COMPOUND_TIDE_RANGE_MIN).divide(span).clamp(0, 1);
  return normRain.multiply(normSM).multiply(normTide).rename("compound_risk").toFloat();
}

// =====================================================================
// 13. SEASON FLAG
// =====================================================================
function getSeasonFlag(t) {
  var month = ee.Number(t.get("month")).toInt();
  var wet   = month.gte(4).and(month.lte(6)).or(month.gte(9).and(month.lte(11)));
  return ee.Image.constant(ee.Number(wet).toInt()).rename("season_wet").toFloat();
}

// =====================================================================
// 14. DRIVER LABEL CREATION (3-Class scheme: 0=no-flood, 1=rain, 2=coastal)
// =====================================================================
// v4.3 (C): the p10/p90 used to normalise RFI/CII define the DRIVER
// LABELS. Fitting them across all 23 events makes the labels of training
// events depend on validation-period data. With the switch on, only
// training events contribute -- which changes the labels, hence default off.
var pctFitEvents = RFICII_PERCENTILES_TRAIN_ONLY
  ? events.filter(function(e) { return e.split === "train"; })
  : events;
print("RFI/CII percentiles fitted on " + pctFitEvents.length + " events" +
      (RFICII_PERCENTILES_TRAIN_ONLY ? " (TRAIN ONLY)" : " (ALL -- v4.2 behaviour)"));

var rawIndexSamples = ee.FeatureCollection(pctFitEvents.map(function(e) {
  var t0 = ee.Date(e.start);
  var t1 = ee.Date(e.end);
  var imergBands = getIMERG(t0, t1);
  var rain       = getRain(t0);
  var sm         = getSM(t0);
  var hydro      = getHydroBands(e.id);
  var freeboard  = getFreeboard(hydro, dem);

  var rawImg = ee.Image.cat([
    imergBands.select("imerg_24h"),
    rain.select("chirps_30d"),
    sm,
    freeboard,
    hydro.select("tide_range_fes")
  ]).clip(keta);

  return rawImg.sample({region: keta, scale: 200, numPixels: 150, seed: 42, geometries: false});
})).flatten();

function getPct1090(bandName) {
  return rawIndexSamples.reduceColumns({
    reducer: ee.Reducer.percentile([10, 90]),
    selectors: [bandName]
  });
}

var pctImerg  = getPct1090("imerg_24h");
var pctChirps = getPct1090("chirps_30d");
var pctSm     = getPct1090("soil_moisture");
var pctFb     = getPct1090("freeboard_fes");
var pctTr     = getPct1090("tide_range_fes");

var rfciiPct = {
  imerg_p10:  ee.Number(pctImerg.get("p10")),  imerg_p90:  ee.Number(pctImerg.get("p90")),
  chirps_p10: ee.Number(pctChirps.get("p10")), chirps_p90: ee.Number(pctChirps.get("p90")),
  sm_p10:     ee.Number(pctSm.get("p10")),     sm_p90:     ee.Number(pctSm.get("p90")),
  fb_p10:     ee.Number(pctFb.get("p10")),     fb_p90:     ee.Number(pctFb.get("p90")),
  tr_p10:     ee.Number(pctTr.get("p10")),     tr_p90:     ee.Number(pctTr.get("p90"))
};

function normB(img, bandName, p10, p90) {
  var b = img.select(bandName);
  var span = ee.Number(p90).subtract(p10);
  var safeSpan = ee.Number(ee.Algorithms.If(span.gt(0.001), span, 1.0));
  return b.subtract(p10).divide(safeSpan).clamp(0, 1);
}

function getRFI(imergBands, rain, sm) {
  var normI = normB(imergBands, "imerg_24h",   rfciiPct.imerg_p10,  rfciiPct.imerg_p90);
  var normC = normB(rain,       "chirps_30d",  rfciiPct.chirps_p10, rfciiPct.chirps_p90);
  var normS = normB(sm,         "soil_moisture",rfciiPct.sm_p10,     rfciiPct.sm_p90);
  return normI.multiply(0.5).add(normC.multiply(0.3)).add(normS.multiply(0.2)).rename("RFI");
}

function getCII(hydro, demImg) {
  var freeboard = getFreeboard(hydro, demImg);
  var normFb = normB(freeboard, "freeboard_fes", rfciiPct.fb_p10, rfciiPct.fb_p90);
  var normTr = normB(hydro,     "tide_range_fes",rfciiPct.tr_p10, rfciiPct.tr_p90);
  return normFb.multiply(0.6).add(normTr.multiply(0.4)).rename("CII");
}

function getDriverLabel(floodMask, imergBands, rain, sm, hydro, demImg) {
  var rfi = getRFI(imergBands, rain, sm);
  var cii = getCII(hydro, demImg);

  var isRain    = rfi.gte(cii);
  var isCoastal = cii.gt(rfi);

  var driverCode = ee.Image.constant(0)
    .where(floodMask.eq(1).and(isRain), 1)
    .where(floodMask.eq(1).and(isCoastal), 2)
    .rename("flood_driver")
    .toInt();

  return driverCode.addBands(rfi).addBands(cii);
}

// =====================================================================
// 15. COMPOSITE FEATURE STACK BUILDER (v4.2 with 28 features)
// =====================================================================
function buildEventStack(event) {
  var t0 = ee.Date(event.start);
  var t1 = ee.Date(event.end);

  var floodImg   = getFloodLabel(ee.Dictionary(event));
  var imergBands = getIMERG(t0, t1);
  var rain       = getRain(t0);
  var era5Bands  = getERA5(t0);
  var sm         = getSM(t0);
  var hydro      = getHydroBands(event.id);
  var compound   = getCompoundRisk(imergBands, sm, hydro);
  var season     = getSeasonFlag(t0);
  var freeboard  = getFreeboard(hydro, dem);

  // Rain Intensity Ratio
  var rainRatio  = imergBands.select("imerg_peak_intensity")
    .divide(rain.select("chirps_30d").add(1.0)).rename("rain_intensity_ratio");

  var driverImg  = getDriverLabel(
    floodImg.select("flood"), imergBands, rain, sm, hydro, dem
  );

  var stack = ee.Image.cat([
    terrainStack,        // 7 bands: elevation, slope, aspect, dist_water, lt3, lt1, lt0
    imergBands,          // 3 bands: imerg_24h, imerg_peak_intensity, imerg_3d
    rain,                // 2 bands: chirps_7d, chirps_30d
    era5Bands,           // 7 bands: solar_rad, u_wind_10m, v_wind_10m, wind_speed, wind_dir, onshore_wind, surface_pressure
    sm,                  // 1 band:  soil_moisture
    hydro,               // 4 bands: tide_max_fes, tide_range_fes, spring_flag_fes, tide_anomaly
    freeboard,           // 1 band:  freeboard_fes
    compound,            // 1 band:  compound_risk
    season,              // 1 band:  season_wet
    rainRatio,           // 1 band:  rain_intensity_ratio
    floodImg.select("flood"),
    // v5.0: every QA band must reach the stack, or the qa_label_ok filter on
    // the export matches nothing and the CSV comes back empty.
    floodImg.select(["qa_s1_ok", "qa_label_ok", "qa_gates_ok", "qa_otsu_separability",
                     "qa_otsu_threshold_db", "qa_flood_fraction",
                     "qa_n_before", "qa_n_during"]),
    driverImg.select(["flood_driver", "RFI", "CII"])
  ]).clip(keta);

  return stack.set({
    "event_id": event.id,
    "split": event.split,
    "confidence": event.confidence
  });
}

// Build feature stacks for all 23 events
var eventStacks = events.map(function(e) {
  return buildEventStack(e);
});

// Export tasks setup
// v5.0 FIX. numPixels 650 with a fixed seed returned the SAME pixels for every
// event, so v4.3's 14,881 rows were really 268 distinct locations x 23 events.
// Exporting without geometry also made every row unmappable.
// ---- v5.0 LABEL GATE REPORT (cheap: constant bands at one point) ----
var gatePt = keta.centroid(1);
print("LABEL GATE per event  [gate = threshold in " + MAX_DROP_DB + ".." +
      MIN_DROP_DB + " dB; eta and extent reported only]:",
  ee.List(eventStacks.map(function(stack) {
    var d = stack.select(["qa_otsu_separability", "qa_otsu_threshold_db",
                          "qa_flood_fraction", "qa_gates_ok", "qa_s1_ok"])
      .reduceRegion({reducer: ee.Reducer.first(), geometry: gatePt, scale: 1000});
    return ee.Dictionary(d).set("event", stack.get("event_id"));
  })));

var allSamples = ee.FeatureCollection(eventStacks.map(function(stack) {
  var evId  = stack.get("event_id");
  var split = stack.get("split");
  var conf  = stack.get("confidence");
  return stack
    // Coordinates as BANDS, added BEFORE the mask so they inherit it.
    .addBands(ee.Image.pixelLonLat())
    // Never sample permanent water.
    .updateMask(permWater.not())
    .sample({
      region: keta,
      scale: 30,
      numPixels: SAMPLES_PER_EVENT,
      seed: 42,
      geometries: false,
      tileScale: 4
    }).map(function(f) {
      return f.set("event_id", evId).set("split", split).set("confidence", conf);
    });
})).flatten();

// v4.3 (A): belt-and-braces. The flood band is already masked for events
// without S1 coverage, but we also drop any row that somehow carries
// qa_s1_ok != 1, so a coverage failure can never reach the training data.
// v5.0: events failing bimodality, plausibility or extent contribute no rows.
var validSamples = allSamples
  .filter(ee.Filter.eq("qa_s1_ok", 1))
  .filter(ee.Filter.eq("qa_label_ok", 1));

print("rows before QA filter:", allSamples.size());
print("rows after  QA filter:", validSamples.size());

Export.table.toDrive({
  collection: validSamples,
  folder: "keta_v5",
  description: "keta_samples_v5_1_all_splits",
  fileFormat: "CSV"
});

Export.table.toDrive({
  collection: validSamples.filter(ee.Filter.neq("flood_driver", 0)),
  folder: "keta_v5",
  description: "keta_samples_driver_v5_1_all_splits",
  fileFormat: "CSV"
});

print("=== GEE SCRIPT v5.1 LOADED  (DEM: Copernicus GLO-30) ===");
print("Rows per event (0 = REJECTED by the v5.0 label gate):",
      allSamples.aggregate_histogram("event_id"));
print("Rows per event after the QA filter:",
      validSamples.aggregate_histogram("event_id"));
print("Total rows:", validSamples.size());
print("");
print("v5.1 changes vs v4.3:");
print(" 1. dist_water was distance-to-LAND (a water mask that determined the");
print("    label on 61% of rows). It is now distance FROM permanent water.");
print(" 2. Sentinel-1 pinned to orbit " + S1_RELATIVE_ORBIT + " " + S1_PASS +
      " (519 of 529 scenes over Keta).");
print(" 3. Label gate = Otsu threshold in [" + MAX_DROP_DB + ", " + MIN_DROP_DB +
      "] dB. Separability and extent are exported but not gated.");
print("    qa_gates_ok = 1 marks the events whose SAR label is defensible.");
print("    ENFORCE_LABEL_GATES=" + ENFORCE_LABEL_GATES +
      (ENFORCE_LABEL_GATES ? " -> failing events export ZERO rows."
                           : " -> gates REPORTED ONLY, nothing rejected."));
print(" 4. " + SAMPLES_PER_EVENT + " samples per event (was 650, which deduplicated to 268");
print("    distinct locations); permanent water excluded; lon/lat exported.");
